mapper.select:
SELECT id, file_no, task_no, settle_date, member_id, file_type, file_name, file_size, file_md5, storage_bucket, storage_path, version, status, publish_time, revoke_time, reissue_time, status_reason, download_count, created_at, updated_at FROM settle_file
AND settle_date = #{settleDate}
AND member_id = #{memberId}
AND file_type = #{fileType}
ORDER BY settle_date DESC, member_id ASC, file_type ASC, version ASC

SELECT id, file_no, task_no, settle_date, member_id, file_type, file_name, file_size, file_md5, storage_bucket, storage_path, version, status, publish_time, revoke_time, reissue_time, status_reason, download_count, created_at, updated_at FROM settle_file WHERE settle_date = #{settleDate} AND status = 'GENERATED'
AND file_type = #{fileType}
AND version = #{version}
ORDER BY member_id ASC, file_type ASC, version ASC

mapper.update:
UPDATE settle_file
SET status = 'PUBLISHED',
    publish_time = NOW(),
    status_reason = #{reason}
WHERE file_no = #{fileNo}
  AND status = 'GENERATED'

UPDATE settle_file
SET status = 'REVOKED',
    revoke_time = NOW(),
    status_reason = #{reason}
WHERE file_no = #{fileNo}
  AND status IN ('GENERATED', 'PUBLISHED')

UPDATE settle_file
SET status = 'REISSUED',
    reissue_time = NOW(),
    status_reason = #{reason}
WHERE file_no = #{fileNo}
  AND status IN ('GENERATED', 'PUBLISHED', 'REVOKED')

UPDATE settle_file
SET download_count = download_count + 1
WHERE file_no = #{fileNo}
